// Разбор входящего сообщения Telegram.
// На выходе: chat_id, query (поисковые слова), is_search (искать или показать подсказку).
const msg = $json.message || {};
const chatId = msg.chat ? msg.chat.id : undefined;
const raw = String(msg.text || '').trim();

// Команды (/start, /help и т.п.) не считаем поиском — на них уйдёт подсказка.
const isCommand = raw.startsWith('/');

// Минимум 2 символа, чтобы по одной букве не вываливать всю таблицу.
const isSearch = Boolean(chatId) && !isCommand && raw.length >= 2;

return [{
  json: {
    chat_id: chatId,
    query: isSearch ? raw : '',
    is_search: isSearch,
  },
}];

// Поиск человека по таблице и проверка на чёрный список.
//
// ─── НАСТРОЙКИ ─── поменяйте под свою таблицу ───────────────────────────
const CONFIG = {
  // Колонка со статусом ЧС (заголовок в первой строке таблицы).
  blacklistColumn: 'ЧС',
  // Какие значения в этой колонке значат «в чёрном списке».
  positiveValues: ['да', 'yes', 'true', '1', '+', 'чс', 'в чс', 'blacklist'],
  // Колонка с именем — показывается первой строкой в карточке.
  nameColumn: 'ФИО',
  // Сколько совпадений максимум показывать в одном ответе.
  maxResults: 10,
};
// ────────────────────────────────────────────────────────────────────────

const request = $('Разбор запроса').first().json;
const chatId = request.chat_id;
const query = String(request.query || '');

// Все слова запроса должны встретиться в строке таблицы (в любых колонках).
const words = query.toLowerCase().split(/\s+/).filter(Boolean);

// Строки таблицы; выкидываем служебный row_number и полностью пустые строки.
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => Object.entries(row)
    .some(([key, value]) => key !== 'row_number' && String(value ?? '').trim() !== ''));

const matches = rows.filter((row) => {
  const haystack = Object.entries(row)
    .filter(([key]) => key !== 'row_number')
    .map(([, value]) => String(value ?? '').toLowerCase())
    .join(' ');
  return words.every((word) => haystack.includes(word));
});

const inBlacklist = (row) => {
  const value = String(row[CONFIG.blacklistColumn] ?? '').trim().toLowerCase();
  return CONFIG.positiveValues.includes(value);
};

let reply;
if (matches.length === 0) {
  reply = `🔍 По запросу «${query}» никого не нашёл.\n`
    + 'Проверьте написание или попробуйте другое слово: фамилию, имя, телефон.';
} else {
  const shown = matches.slice(0, CONFIG.maxResults);
  const cards = shown.map((row) => {
    const status = inBlacklist(row) ? '⛔ В ЧЁРНОМ СПИСКЕ' : '✅ Не в чёрном списке';
    const name = String(row[CONFIG.nameColumn] ?? '').trim() || '(без имени)';
    const details = Object.entries(row)
      .filter(([key, value]) => key !== 'row_number'
        && key !== CONFIG.nameColumn
        && key !== CONFIG.blacklistColumn
        && String(value ?? '').trim() !== '')
      .map(([key, value]) => `· ${key}: ${value}`)
      .join('\n');
    return `${status}\n👤 ${name}${details ? '\n' + details : ''}`;
  });
  const header = matches.length > CONFIG.maxResults
    ? `Найдено совпадений: ${matches.length}, показываю первые ${CONFIG.maxResults}.\n\n`
    : `Найдено совпадений: ${matches.length}\n\n`;
  reply = header + cards.join('\n\n————————————\n\n');
}

return [{ json: { chat_id: chatId, reply } }];
